const story = $('Fetch Approved Stories').first().json;
const fetched = $('Fetch Linked Assets').all().map(x => x.json);
const downloaded = $input.all().map(x => x.json);
const byIndex = new Map();
for (let i = 0; i < fetched.length; i++) {
  const a = { ...fetched[i], imageBase64: (downloaded[i] && downloaded[i].imageBase64) || '' };
  const idx = Number(a['Slide Index']);
  if (idx >= 1 && idx <= 6) byIndex.set(idx, a);
}
const assets = [...byIndex.entries()].sort((a, b) => a[0] - b[0]).map(([, a]) => a);
if (assets.length === 0) throw new Error('No Assets with Slide Index 1-6 found for Story ' + story.id);
return [{
  json: {
    storyId: story.id,
    title: story.Title,
    pillar: story.Pillar,
    story,
    assets,
    xThread: {
      post1: (story.Title || '') + ' — ' + (story.Glance || ''),
      post2: (story.Remember || '') + ' (1/2 → 2/2)'
    }
  }
}];

// #!/usr/bin/env node
'use strict';

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function wrapLines(text, maxChars, maxLines) {
  const words = String(text || '').trim().split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = '';
  for (const w of words) {
    if (!cur) {
      cur = w;
    } else if ((cur + ' ' + w).length <= maxChars) {
      cur += ' ' + w;
    } else {
      lines.push(cur);
      cur = w;
      if (maxLines && lines.length >= maxLines) break;
    }
  }
  if (cur && (!maxLines || lines.length < maxLines)) lines.push(cur);
  if (maxLines && lines.length === maxLines && words.join(' ').length > lines.join(' ').length) {
    lines[maxLines - 1] = lines[maxLines - 1].replace(/\s*\S*$/, '') + '...';
  }
  return lines;
}

function splitSentences(text) {
  return String(text || '').trim().replace(/\s+/g, ' ').split(/(?<=[.!?])\s+/).filter(Boolean);
}

function buildParagraphBlocks(paragraphs, maxChars, maxTotalLines) {
  const blocks = [];
  let used = 0;
  for (const p of paragraphs) {
    const clean = String(p || '').trim();
    if (!clean) continue;
    const remaining = maxTotalLines - used;
    if (remaining <= 0) break;
    const lines = wrapLines(clean, maxChars, remaining);
    if (lines.length) {
      blocks.push(lines);
      used += lines.length;
    }
  }
  return blocks;
}

function buildNarrativeSections(story, count) {
  const glanceSentences = splitSentences(story.Glance);
  const exploreParas = String(story.Explore || '').split(/\n+/).map(s => s.trim()).filter(Boolean);
  const deepParas = String(story['Deep Dive'] || '').split(/\n+/).map(s => s.trim()).filter(Boolean);
  const rememberText = String(story.Remember || '').trim();

  const coverSubtitle = glanceSentences[0] ? '(' + glanceSentences[0] + ')' : '';
  const sections = [
    { kind: 'cover', heading: String(story.Title || '').trim(), paragraphs: coverSubtitle ? [coverSubtitle] : [] }
  ];

  const bodyPool = [];
  if (glanceSentences.length > 1) {
    bodyPool.push({ heading: 'The Hook', paragraphs: [glanceSentences.slice(1).join(' ')] });
  }
  if (exploreParas.length >= 1) {
    const expSent = splitSentences(exploreParas[0]);
    if (exploreParas.length === 1 && expSent.length >= 3) {
      const mid = Math.ceil(expSent.length / 2);
      bodyPool.push({ heading: 'The Problem', paragraphs: [expSent.slice(0, mid).join(' ')] });
      bodyPool.push({ heading: 'Why It Mattered', paragraphs: [expSent.slice(mid).join(' ')] });
    } else {
      bodyPool.push({ heading: 'The Problem', paragraphs: exploreParas.slice(0, 2) });
    }
  }
  for (let i = 0; i < deepParas.length; i++) {
    const ddSent = splitSentences(deepParas[i]);
    const headings = ['The Craft & Turning Point', 'The Breakthrough', 'The Proof'];
    if (deepParas.length === 1 && ddSent.length >= 3) {
      const mid = Math.ceil(ddSent.length / 2);
      bodyPool.push({ heading: 'The Craft & Turning Point', paragraphs: [ddSent.slice(0, mid).join(' ')] });
      bodyPool.push({ heading: 'The Breakthrough', paragraphs: [ddSent.slice(mid).join(' ')] });
    } else {
      bodyPool.push({ heading: headings[i] || 'The Story', paragraphs: [deepParas[i]] });
    }
  }

  const middleSlots = Math.max(0, count - 2);
  for (let i = 0; i < middleSlots; i++) {
    sections.push(bodyPool[i] || { heading: 'The Story', paragraphs: [story.Explore || story.Glance || ''] });
  }

  if (count >= 2) {
    sections.push({
      kind: 'legacy',
      heading: 'The Legacy',
      paragraphs: rememberText ? [rememberText] : [story.Glance || '']
    });
  }

  return sections.slice(0, count);
}

function buildCarouselSlides(story, assets) {
  if (!story || !story.Title) throw new Error('Missing Story Title');
  const byIndex = new Map();
  for (const a of (assets || [])) {
    const idx = Number(a['Slide Index']);
    if (idx >= 1 && idx <= 7) byIndex.set(idx, a);
  }
  const maxAssetIdx = byIndex.size ? Math.max(...byIndex.keys()) : 0;
  const totalSlides = Math.max(6, maxAssetIdx);
  const sections = buildNarrativeSections(story, totalSlides);

  const slides = [];
  for (let i = 1; i <= totalSlides; i++) {
    const asset = byIndex.get(i) || null;
    const sec = sections[i - 1] || { kind: 'body', heading: story.Title, paragraphs: [] };
    const hasPhoto = Boolean(asset && (asset.imageBase64 || (Array.isArray(asset.File) && asset.File[0] && asset.File[0].url)));
    slides.push({
      slideIndex: i,
      totalSlides,
      kind: sec.kind || 'body',
      style: hasPhoto ? (asset.style || 'photo') : 'card',
      pillar: String(story.Pillar || 'WE, HUMANITY').toUpperCase(),
      heading: (asset && asset.overlayHeading) ? String(asset.overlayHeading) : sec.heading,
      paragraphs: (asset && asset.overlayBody) ? [String(asset.overlayBody)] : sec.paragraphs,
      credit: asset ? asset.Credit : '',
      license: asset ? (asset.License || '') : '',
      aiGenerated: Boolean(asset && asset['AI Generated']),
      imageBase64: asset ? (asset.imageBase64 || '') : '',
      imageMime: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].type) || 'image/jpeg',
      imageUrl: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].url) || '',
    });
  }
  return slides;
}

function renderSlideSvg(slide) {
  const slideCounter = String(slide.slideIndex).padStart(2, '0') + ' / ' + String(slide.totalSlides).padStart(2, '0');

  if (slide.style === 'card') {
    const headingLines = wrapLines(slide.heading, 28, 3);
    const paraBlocks = buildParagraphBlocks(slide.paragraphs, 56, 15);
    const headLH = 56;
    const bodyLH = 40;
    const paraGap = 24;

    let bodyLinesCount = 0;
    for (const b of paraBlocks) bodyLinesCount += b.length;
    const bodyH = bodyLinesCount * bodyLH + Math.max(0, paraBlocks.length - 1) * paraGap;
    const totalH = headingLines.length * headLH + 28 + bodyH;
    const startY = Math.max(240, Math.round((1350 - totalH) / 2));

    const headEls = headingLines.map((l, i) =>
      `<text x="84" y="${startY + i * headLH}" fill="#171715" font-family="Helvetica Neue, Inter, sans-serif" font-size="46" font-weight="700" letter-spacing="-0.5">${esc(l)}</text>`
    ).join('\n  ');

    let curY = startY + headingLines.length * headLH + 34;
    const bodyEls = [];
    for (const block of paraBlocks) {
      for (const line of block) {
        bodyEls.push(`<text x="84" y="${curY}" fill="#2F2F2B" font-family="Helvetica Neue, Inter, sans-serif" font-size="28" font-weight="400">${esc(line)}</text>`);
        curY += bodyLH;
      }
      curY += paraGap;
    }

    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <rect width="1080" height="1350" fill="#F6F4EF"/>
  <rect x="36" y="36" width="1008" height="1278" rx="16" fill="none" stroke="#DDD8CC" stroke-width="2"/>
  <text x="84" y="96" fill="#1D4ED8" font-family="Helvetica Neue, Inter, sans-serif" font-size="18" font-weight="700" letter-spacing="2">${esc(slide.pillar)}</text>
  <text x="996" y="96" text-anchor="end" fill="#5E5D58" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="600" letter-spacing="2">${esc(slideCounter)}</text>
  ${headEls}
  ${bodyEls.join('\n  ')}
  <text x="84" y="1274" fill="#171715" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="700" letter-spacing="2">WE, HUMANITY</text>
</svg>`;
  }

  const imgHref = slide.imageBase64
    ? ('data:' + slide.imageMime + ';base64,' + slide.imageBase64)
    : (slide.imageUrl ? esc(slide.imageUrl) : '');

  const creditText = slide.aiGenerated ? 'Visual synthesis via Gemini Flash Image (WE, HUMANITY)' : slide.credit;
  const creditShort = wrapLines(creditText, 88, 1)[0] || '';

  let textSvg = '';
  if (slide.kind === 'cover') {
    const titleLines = wrapLines(slide.heading, 24, 3);
    const subLines = slide.paragraphs[0] ? wrapLines(slide.paragraphs[0], 56, 6) : [];
    const titleLH = 64;
    const subLH = 35;
    const totalH = titleLines.length * titleLH + (subLines.length ? 24 + subLines.length * subLH : 0);
    const startY = Math.max(660, 1215 - totalH);

    const titleEls = titleLines.map((l, i) =>
      `<text x="80" y="${startY + i * titleLH}" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="54" font-weight="700" letter-spacing="-0.5" filter="url(#textShadow)">${esc(l)}</text>`
    ).join('\n  ');

    const subStartY = startY + titleLines.length * titleLH + 22;
    const subEls = subLines.map((l, i) =>
      `<text x="80" y="${subStartY + i * subLH}" fill="#F3F1EC" fill-opacity="0.94" font-family="Helvetica Neue, Inter, sans-serif" font-size="25" font-weight="400" filter="url(#textShadow)">${esc(l)}</text>`
    ).join('\n  ');

    textSvg = titleEls + '\n  ' + subEls;
  } else {
    const headingLines = wrapLines(slide.heading, 28, 2);
    const paraBlocks = buildParagraphBlocks(slide.paragraphs, 56, 14);
    const headLH = 52;
    const bodyLH = 36;
    const paraGap = 18;

    let bodyLinesCount = 0;
    for (const b of paraBlocks) bodyLinesCount += b.length;
    const bodyH = bodyLinesCount * bodyLH + Math.max(0, paraBlocks.length - 1) * paraGap;
    const totalH = headingLines.length * headLH + 22 + bodyH;
    const startY = Math.max(460, 1215 - totalH);

    const headEls = headingLines.map((l, i) =>
      `<text x="80" y="${startY + i * headLH}" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="42" font-weight="700" letter-spacing="-0.3" filter="url(#textShadow)">${esc(l)}</text>`
    ).join('\n  ');

    let curY = startY + headingLines.length * headLH + 26;
    const bodyEls = [];
    for (const block of paraBlocks) {
      for (const line of block) {
        bodyEls.push(`<text x="80" y="${curY}" fill="#F5F3EE" fill-opacity="0.95" font-family="Helvetica Neue, Inter, sans-serif" font-size="25" font-weight="400" filter="url(#textShadow)">${esc(line)}</text>`);
        curY += bodyLH;
      }
      curY += paraGap;
    }

    textSvg = headEls + '\n  ' + bodyEls.join('\n  ');
  }

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <defs>
    <linearGradient id="editorialScrim" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="#0B0B0A" stop-opacity="0.35"/>
      <stop offset="28%" stop-color="#0B0B0A" stop-opacity="0.05"/>
      <stop offset="50%" stop-color="#0B0B0A" stop-opacity="0.56"/>
      <stop offset="100%" stop-color="#0B0B0A" stop-opacity="0.90"/>
    </linearGradient>
    <filter id="textShadow" x="-10%" y="-10%" width="120%" height="120%">
      <feDropShadow dx="0" dy="2" stdDeviation="5" flood-color="#000000" flood-opacity="0.6"/>
    </filter>
  </defs>
  <rect width="1080" height="1350" fill="#181816"/>
  ${imgHref ? `<image href="${imgHref}" x="0" y="0" width="1080" height="1350" preserveAspectRatio="xMidYMid slice"/>` : ''}
  <rect width="1080" height="1350" fill="url(#editorialScrim)"/>
  ${slide.slideIndex === 1 ? `<text x="80" y="88" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="26" font-weight="700" letter-spacing="3" filter="url(#textShadow)">WH</text>` : ''}
  <text x="1000" y="88" text-anchor="end" fill="#FFFFFF" fill-opacity="0.85" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="600" letter-spacing="2" filter="url(#textShadow)">${esc(slideCounter)}</text>
  ${textSvg}
  ${creditShort ? `<text x="80" y="1312" fill="#E6E4DF" fill-opacity="0.78" font-family="Helvetica Neue, Inter, sans-serif" font-size="14" filter="url(#textShadow)">${esc(creditShort)}</text>` : ''}
</svg>`;
}

const payload = $input.first().json;
const slides = buildCarouselSlides(payload.story, payload.assets);
const credits = slides.filter(s => s.credit).map(s => `${s.slideIndex}. ${s.credit}`).join('\n');
const linkedinCaption = `${payload.title}\n\n${payload.story.Glance || ''}\n\n${payload.story.Remember || ''}${credits ? `\n\nCredits:\n${credits}` : ''}`;
const instagramCaption = `${payload.title}\n\n${payload.story.Glance || ''}\n\nSwipe through for the full story.${payload.story.Remember ? `\n\n${payload.story.Remember}` : ''}`;
const out = [];
for (const s of slides) {
  const svg = renderSlideSvg(s);
  const filename = `${payload.storyId}_slide_${s.slideIndex}.svg`;
  out.push({
    json: {
      storyId: payload.storyId,
      slideIndex: s.slideIndex,
      title: payload.title,
      pillar: payload.pillar,
      svg,
      filename,
      localPath: `/Users/admin/Documents/My Workspace/we-humanity-wf3c/renders/${filename}`,
      linkedinCaption,
      instagramCaption,
      xThread: payload.xThread
    },
    pairedItem: { item: 0 }
  });
}
return out;
